import Foundation
import SwiftData

@Model
final class Dog {
    var name: String
    var breed: String
    var ageYears: Int
    var weightKg: Double
    @Attribute(.externalStorage) var photoData: Data?
    var createdAt: Date

    init(name: String, breed: String, ageYears: Int, weightKg: Double, photoData: Data? = nil) {
        self.name = name
        self.breed = breed
        self.ageYears = ageYears
        self.weightKg = weightKg
        self.photoData = photoData
        self.createdAt = .now
    }
}
